-- Phase C6.1: per-generator, per-maintenance-item oil requirement.
-- No defaults are inserted: the commercial administrator chooses the stocked oil and quantity.

CREATE TABLE IF NOT EXISTS "GeneratorMaintenanceOilConfigurations" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "GeneratorId" integer NOT NULL REFERENCES "Generators" ("Id") ON DELETE RESTRICT,
    "ServiceItemId" integer NOT NULL REFERENCES "ServiceItems" ("Id") ON DELETE RESTRICT,
    "OilId" integer NOT NULL REFERENCES "Oils" ("Id") ON DELETE RESTRICT,
    "QuantityLiters" numeric(18,3) NOT NULL CHECK ("QuantityLiters" > 0),
    "IsActive" boolean NOT NULL DEFAULT TRUE,
    "CreatedAt" timestamp with time zone NOT NULL,
    "CreatedBy" integer NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "UpdatedBy" integer NOT NULL,
    "DeletedAt" timestamp with time zone NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "UX_GeneratorMaintenanceOilConfigurations_Generator_Item"
    ON "GeneratorMaintenanceOilConfigurations" ("GeneratorId", "ServiceItemId")
    WHERE "DeletedAt" IS NULL;
CREATE INDEX IF NOT EXISTS "IX_GeneratorMaintenanceOilConfigurations_Oil"
    ON "GeneratorMaintenanceOilConfigurations" ("OilId") WHERE "DeletedAt" IS NULL;
